const config = {
  "previewFeatures": [],
  "clientVersion": "7.7.0",
  "engineVersion": "75cbdc1eb7150937890ad5465d861175c6624711",
  "activeProvider": "postgresql",
  "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ═══════════════════════════════════════════════════════════════\n// BOT SYSTEM — Digital User Models\n// ═══════════════════════════════════════════════════════════════\n\nenum BotType {\n  SEED // 种子用户，冷启动用\n  SIMULATION // 行为模拟用户\n  TRAINING // 训练数据生成\n  ACTIVE // 活跃参与匹配\n}\n\nenum BotActivityLevel {\n  GHOST // 隐身，仅匹配不可见\n  LOW // 低活跃度 (10% 在线时间)\n  MEDIUM // 中活跃度 (30% 在线时间)\n  HIGH // 高活跃度 (60% 在线时间)\n  FULL // 全天候在线\n}\n\nenum Ethnicity {\n  CAUCASIAN\n  AFRICAN_AMERICAN\n  HISPANIC_LATINO\n  ASIAN\n  SOUTH_ASIAN\n  MIDDLE_EASTERN\n  MIXED\n  OTHER\n}\n\nenum OnlinePattern {\n  MORNING // 6AM-12PM\n  AFTERNOON // 12PM-6PM\n  EVENING // 6PM-12AM\n  NIGHT // 12AM-6AM\n  RANDOM\n  WORK_HOURS // 9AM-5PM\n  AFTER_WORK // 5PM-10PM\n}\n\n// Bot扩展资料 - 数字用户详细信息\nmodel BotProfile {\n  id        String  @id @default(cuid())\n  profileId String  @unique\n  profile   Profile @relation(fields: [profileId], references: [id], onDelete: Cascade)\n\n  // 基础配置\n  botType       BotType          @default(SEED)\n  activityLevel BotActivityLevel @default(LOW)\n\n  // 人口统计扩展\n  ethnicity      Ethnicity?\n  occupation     String? // \"Software Engineer\", \"Teacher\", etc.\n  industry       String? // \"Tech\", \"Healthcare\", \"Finance\", etc.\n  educationLevel String? // \"High School\", \"Bachelor's\", \"Master's\", \"PhD\"\n  incomeRange    String? // \"$30k-50k\", \"$50k-100k\", etc.\n\n  // 兴趣与偏好\n  interests   String[] // [\"hiking\", \"cooking\", \"photography\"]\n  hobbies     String[] // [\"gaming\", \"yoga\", \"reading\"]\n  musicGenres String[] // [\"rock\", \"jazz\", \"electronic\"]\n  movieGenres String[] // [\"thriller\", \"romance\", \"sci-fi\"]\n\n  // 行为模拟配置\n  onlinePattern   OnlinePattern @default(EVENING)\n  avgResponseTime Int           @default(30) // 平均响应时间（分钟）\n  maxDailyMatches Int           @default(3) // 每日最大匹配数\n\n  // 行为概率配置（JSON）\n  behaviorConfig String? @db.Text\n\n  // 匹配偏好（扩展 Profile 的 preferred* 字段）\n  preferredEthnicities Ethnicity[]\n  preferredOccupations String[]\n  preferredEducation   String[]\n\n  // 学习状态\n  totalInteractions  Int   @default(0)\n  successfulMatches  Int   @default(0)\n  avgEngagementScore Float @default(0) // 0-100\n\n  // 学习数据（JSON）\n  learningData String? @db.Text\n\n  // 头像配置\n  avatarStyle  String? // \"professional\", \"casual\", \"artistic\"\n  avatarSource String? // \"generated\", \"stock\", \"ai_avatar\"\n\n  // 状态\n  isActive     Boolean   @default(true)\n  lastActiveAt DateTime?\n  sleepUntil   DateTime? // 暂停到指定时间\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([botType])\n  @@index([activityLevel])\n  @@index([isActive])\n}\n\n// Bot行为交互日志\nmodel BotInteractionLog {\n  id           String  @id @default(cuid())\n  botUserId    String\n  targetUserId String?\n  matchId      String?\n\n  // 交互类型\n  interactionType String // \"match_received\", \"match_reacted\", \"message_sent\", \"message_received\", \"profile_viewed\"\n\n  // 行为详情\n  action        String // \"accept\", \"pass\", \"respond\", \"initiate\"\n  responseDelay Int? // 响应延迟（秒）\n\n  // 结果\n  outcome         String? // \"success\", \"rejected\", \"no_response\", \"blocked\"\n  engagementScore Int? // 0-100 参与度评分\n\n  // 上下文\n  context String? @db.Text // JSON: {matchScore, matchReason, etc.}\n\n  createdAt DateTime @default(now())\n\n  @@index([botUserId, createdAt])\n  @@index([interactionType])\n  @@index([outcome])\n}\n\n// Bot学习批次\nmodel BotLearningBatch {\n  id String @id @default(cuid())\n\n  // 批次信息\n  batchNumber Int\n  status      String @default(\"pending\") // pending, running, completed, failed\n\n  // 数据范围\n  startDate DateTime\n  endDate   DateTime\n\n  // 统计数据\n  totalInteractions Int   @default(0)\n  avgEngagement     Float @default(0)\n  successRate       Float @default(0)\n\n  // 更新的偏好配置\n  preferenceUpdates String? @db.Text // JSON array of changes\n\n  // 执行日志\n  executionLog String? @db.Text\n\n  createdAt   DateTime  @default(now())\n  completedAt DateTime?\n\n  @@index([status])\n  @@index([batchNumber])\n}\n\n// Bot学习记录 - 实时交互数据\nmodel BotLearningRecord {\n  id     String @id @default(cuid())\n  botId  String\n  userId String // 交互对象用户ID\n\n  // 交互类型\n  interactionType String // MATCH_REQUEST, MATCH_ACCEPT, CHAT_MESSAGE, etc.\n  outcome         String // POSITIVE, NEUTRAL, NEGATIVE\n\n  // 上下文数据\n  context Json? // 存储额外上下文\n\n  // 处理状态\n  processed Boolean @default(false)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([botId])\n  @@index([processed])\n  @@index([createdAt])\n  @@index([interactionType])\n}\n\n// Bot偏好向量 - 学习结果\nmodel BotPreference {\n  id    String @id @default(cuid())\n  botId String @unique\n\n  // 五维偏好 (0-1)\n  relationshipStructure Float @default(0.5)\n  communicationStyle    Float @default(0.5)\n  interests             Float @default(0.5)\n  values                Float @default(0.5)\n  lifestyle             Float @default(0.5)\n\n  // 元数据\n  confidence Float @default(0.1) // 置信度 (0-1)\n  sampleSize Int   @default(0) // 样本数量\n\n  createdAt   DateTime @default(now())\n  lastUpdated DateTime @updatedAt\n\n  @@index([botId])\n}\n\n// Bot头像管理\nmodel BotAvatar {\n  id           String  @id @default(cuid())\n  botId        String  @unique\n  originalUrl  String?\n  processedUrl String? // 处理后（压缩、优化）的URL\n\n  style     String // 原始风格\n  ethnicity String // 原始种族标签\n\n  status   String @default(\"pending\") // pending, active, failed, retired\n  useCount Int    @default(0) // 使用次数\n\n  generatedAt DateTime  @default(now())\n  lastUsedAt  DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ═══════════════════════════════════════════════════════════════\n// AUTH — NextAuth v5 compatible models\n// ═══════════════════════════════════════════════════════════════\n\nmodel User {\n  id            String    @id @default(cuid())\n  name          String?\n  email         String    @unique\n  emailVerified DateTime?\n  image         String?\n\n  // Auth\n  password String?\n  role     UserRole  @default(USER)\n  accounts Account[]\n  sessions Session[]\n\n  // Bot/Digital User Flags\n  isBot     Boolean @default(false) // 标记是否为数字用户\n  botType   String? // \"simulation\" | \"training\" | \"seed\"\n  botConfig String? @db.Text // 数字用户行为配置（JSON字符串存储）\n\n  // Email Verification\n  verificationTokens VerificationToken[] @relation(\"UserVerificationTokens\")\n\n  // Profile\n  profile Profile?\n\n  // Matching\n  sentMatches     Match[]         @relation(\"SentMatches\")\n  receivedMatches Match[]         @relation(\"ReceivedMatches\")\n  matchReactions  MatchReaction[]\n\n  // Chat\n  chatRooms ChatRoomMember[]\n  messages  Message[]\n\n  // IM Module\n  conversationsA      Conversation[]            @relation(\"ConversationUserA\")\n  conversationsB      Conversation[]            @relation(\"ConversationUserB\")\n  imMessages          IMMessage[]               @relation(\"IMMessageSender\")\n  messageReceipts     MessageReceipt[]\n  messageReactions    MessageReaction[]\n  imParticipants      ConversationParticipant[]\n  presence            UserPresence?\n  powerBoardRule      PowerBoardRule?\n  consentRequestsMade ConsentRequest[]          @relation(\"ConsentRequester\")\n  consentRequestsRecv ConsentRequest[]          @relation(\"ConsentTarget\")\n  consentGrantsMade   ConsentGrant[]            @relation(\"ConsentGranter\")\n  consentGrantsRecv   ConsentGrant[]            @relation(\"ConsentGrantee\")\n  auditLogs           AuditLog[]\n\n  // Payments\n  subscriptions Subscription[]\n  payments      Payment[]\n\n  // Notifications\n  notifications Notification[]\n\n  // Admin\n  adminLogs AdminLog[] @relation(\"AdminLogAuthor\")\n\n  // Analytics\n  analyticsEvents AnalyticsEvent[]\n\n  // Safety & Moderation\n  reportsMade     UserReport[] @relation(\"ReportsMade\")\n  reportsReceived UserReport[] @relation(\"ReportsReceived\")\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([email])\n  @@index([role])\n  @@index([createdAt])\n}\n\nmodel Account {\n  id                String  @id @default(cuid())\n  userId            String\n  type              String\n  provider          String\n  providerAccountId String\n  refresh_token     String? @db.Text\n  access_token      String? @db.Text\n  expires_at        Int?\n  token_type        String?\n  scope             String?\n  id_token          String? @db.Text\n  session_state     String?\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([provider, providerAccountId])\n}\n\nmodel Session {\n  id           String   @id @default(cuid())\n  sessionToken String   @unique\n  userId       String\n  expires      DateTime\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\nmodel VerificationToken {\n  id         String    @id @default(cuid())\n  identifier String // email address\n  token      String    @unique // the 6-digit code\n  expires    DateTime\n  userId     String? // optional link to user\n  user       User?     @relation(\"UserVerificationTokens\", fields: [userId], references: [id], onDelete: Cascade)\n  used       Boolean   @default(false)\n  useCount   Int       @default(0) // Track usage count for replay attack prevention\n  maxUses    Int       @default(1) // Maximum allowed uses (1 for one-time tokens)\n  lastUsedAt DateTime? // Track when token was last used\n  createdAt  DateTime  @default(now())\n\n  @@unique([identifier, token])\n  @@index([identifier])\n  @@index([userId])\n  @@index([expires])\n}\n\n// ═══════════════════════════════════════════════════════════════\n// USER PROFILE — Relationship structure blueprint\n// ═══════════════════════════════════════════════════════════════\n\nmodel Profile {\n  id     String @id @default(cuid())\n  userId String @unique\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // Basic Info\n  displayName    String\n  age            Int\n  gender         Gender\n  genderIdentity String? // Free text for non-binary identification\n  sexuality      String // \"Straight\", \"Bisexual\", \"Pansexual\", \"Queer\", \"Lesbian\", \"Gay\", \"Fluid\", etc.\n  bio            String?  @db.Text\n  avatar         String? // Upload URL\n  avatarType     String? // \"photo\" | \"cartoon\"\n  galleryPhotos  String[] @default([]) // User photo album URLs\n  city           String?\n  country        String?  @default(\"US\")\n\n  // Relationship Blueprint (核心差异化数据)\n  relationshipGoal      RelationshipGoal @default(LONG_TERM)\n  attachmentStyle       String? // \"Secure\", \"Anxious-Preoccupied\", \"Dismissive-Avoidant\", \"Fearful-Avoidant\"\n  communicationStyle    String? // \"Direct\", \"Reflective\", \"Expressive\", \"Analytical\"\n  conflictResolution    String? // \"Collaborative\", \"Compromising\", \"Accommodating\", \"Competing\", \"Avoiding\"\n  loveLanguage          String? // \"Words of Affirmation\", \"Quality Time\", \"Physical Touch\", \"Acts of Service\", \"Gifts\"\n  boundaries            String?          @db.Text // JSON array of boundary descriptions\n  dealbreakers          String?          @db.Text // JSON array\n  lifePriorities        String?          @db.Text // JSON array: \"Career\", \"Family\", \"Adventure\", \"Stability\", etc.\n  emotionalAvailability String? // \"Fully Available\", \"Building Trust\", \"Processing Past\", \"Needs Space\"\n\n  // ═══════════════════════════════════════════════════════════════\n  // NEW: User Preference Tags for Matching (最多5个)\n  // ═══════════════════════════════════════════════════════════════\n  selectedTags String[] @default([]) // 用户选择的标签，如 [\"MONOGAMY\", \"KINK\", \"BISEXUAL\"]\n\n  // Preferences for matching\n  preferredAgeMin   Int?\n  preferredAgeMax   Int?\n  preferredGender   String?\n  preferredDistance Int? // Max distance in miles\n  preferredLocation String?\n\n  // Matching score cache (denormalized for performance)\n  compatibilityScore Int? // 0-100 overall score\n\n  // Status\n  profileStatus  ProfileStatus @default(DRAFT)\n  onboardingStep Int           @default(0) // 0-5, tracks onboarding progress\n  isApproved     Boolean       @default(false)\n  isVerified     Boolean       @default(false)\n\n  // Personality & Matching Data (for bot users)\n  personalityData String? @db.Text // 完整人格数据存储（JSON字符串）\n\n  // Admin notes\n  adminNotes String? @db.Text\n\n  // Bot System Relation\n  botProfile BotProfile?\n\n  // ═══════════════════════════════════════════════════════════════\n  // PRODUCT OPTIMIZATION: Elite Power Features\n  // ═══════════════════════════════════════════════════════════════\n\n  // Professional Info\n  occupation        String? // Job title\n  company           String? // Company name\n  industry          String? // Industry sector\n  linkedInVerified  Boolean @default(false)\n  verificationBadge String? // \"VERIFIED\", \"ELITE\", etc.\n\n  // Sincerity System\n  sincerityWallet SincerityWallet?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([gender])\n  @@index([relationshipGoal])\n  @@index([profileStatus])\n  @@index([compatibilityScore])\n  @@index([linkedInVerified])\n}\n\n// ═══════════════════════════════════════════════════════════════\n// MATCHING ENGINE — Core differentiation\n// ═══════════════════════════════════════════════════════════════\n\nmodel Match {\n  id String @id @default(cuid())\n\n  // Participants\n  senderId   String\n  sender     User   @relation(\"SentMatches\", fields: [senderId], references: [id])\n  receiverId String\n  receiver   User   @relation(\"ReceivedMatches\", fields: [receiverId], references: [id])\n\n  // Matching Data\n  matchScore       Float // 0-100 compatibility score\n  matchReason      String  @db.Text // AI-generated explanation of why they match\n  conflictWarnings String? @db.Text // JSON array of potential conflicts\n\n  // Compatibility breakdown (denormalized)\n  attachmentCompat    Float? // 0-100\n  communicationCompat Float? // 0-100\n  conflictCompat      Float? // 0-100\n  valuesCompat        Float? // 0-100\n  lifestyleCompat     Float? // 0-100\n\n  // Status\n  status    MatchStatus @default(PENDING)\n  matchType MatchType   @default(WEEKLY)\n\n  // Reaction tracking\n  matchReactions MatchReaction[]\n  senderAction   MatchAction?\n  receiverAction MatchAction?\n\n  // Connection\n  chatRoom ChatRoom?\n\n  // Admin\n  reviewedBy  String?\n  reviewNotes String? @db.Text\n\n  // ═══════════════════════════════════════════════════════════════\n  // PRODUCT OPTIMIZATION: Elite Power Features\n  // ═══════════════════════════════════════════════════════════════\n\n  // Pitch Message (申请信)\n  pitchMessage String? @db.Text // 50-200字申请信\n  pitchTone    String? // \"casual\", \"sincere\", \"playful\", \"direct\"\n  aiAssisted   Boolean @default(false) // 是否使用AI辅助\n\n  // Sincerity Gift (诚意值附赠)\n  giftAmount Int @default(0) // 附赠诚意值数量\n\n  // Inbox Management (收件箱管理)\n  isUnread      Boolean @default(true) // 是否未读\n  inboxPriority Float? // 收件箱排序权重 (计算值)\n\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n  expiresAt DateTime? // Auto-expire after 7 days if not acted on\n\n  @@unique([senderId, receiverId], map: \"unique_match_pair\")\n  @@index([status])\n  @@index([matchScore])\n  @@index([matchType])\n  @@index([createdAt])\n  @@index([expiresAt])\n  @@index([senderId])\n  @@index([receiverId])\n  @@index([senderId, receiverId])\n  @@index([isUnread])\n  @@index([inboxPriority])\n}\n\nmodel MatchReaction {\n  id      String @id @default(cuid())\n  matchId String\n  match   Match  @relation(fields: [matchId], references: [id], onDelete: Cascade)\n  userId  String\n  user    User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  reaction MatchAction\n  feedback String?     @db.Text // Optional feedback on why\n\n  createdAt DateTime @default(now())\n\n  @@unique([matchId, userId])\n  @@index([userId])\n}\n\n// ═══════════════════════════════════════════════════════════════\n// REAL-TIME CHAT (Legacy - backwards compatible)\n// ═══════════════════════════════════════════════════════════════\n\nmodel ChatRoom {\n  id String @id @default(cuid())\n\n  match   Match?  @relation(fields: [matchId], references: [id])\n  matchId String? @unique\n\n  members  ChatRoomMember[]\n  messages Message[]\n\n  lastMessageAt DateTime?\n  isArchived    Boolean   @default(false)\n\n  // ═══════════════════════════════════════════════════════════════\n  // PRODUCT OPTIMIZATION: The 24h Vault\n  // ═══════════════════════════════════════════════════════════════\n\n  // Vault Status\n  vaultStatus VaultStatus @default(ACTIVE) // ACTIVE, EXTENDED, REVOKED, EXPIRED\n\n  // Vault Timer\n  vaultExpiry    DateTime? // 24h倒计时过期时间\n  extendedAt     DateTime? // 延长时间点\n  extendedBy     String? // 谁延长了\n  extensionCount Int       @default(0) // 延长次数\n\n  // Female Controls (女性特权)\n  revokedAt    DateTime? // 被终止时间\n  revokedBy    String? // 谁终止了\n  revokeReason String? // 终止原因\n\n  // Privacy Protection\n  screenshotCount  Int       @default(0) // 检测到的截图次数\n  lastScreenshotAt DateTime? // 最后一次截图时间\n\n  // IM Module: link to Conversation (1:1)\n  conversation Conversation?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([vaultStatus])\n  @@index([vaultExpiry])\n}\n\nmodel ChatRoomMember {\n  id     String   @id @default(cuid())\n  roomId String\n  room   ChatRoom @relation(fields: [roomId], references: [id], onDelete: Cascade)\n  userId String\n  user   User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  lastReadAt DateTime?\n  isMuted    Boolean   @default(false)\n\n  joinedAt DateTime @default(now())\n\n  @@unique([roomId, userId])\n  @@index([userId])\n}\n\nmodel Message {\n  id       String   @id @default(cuid())\n  roomId   String\n  room     ChatRoom @relation(fields: [roomId], references: [id], onDelete: Cascade)\n  senderId String\n  sender   User     @relation(fields: [senderId], references: [id])\n\n  content     String      @db.Text\n  messageType MessageType @default(TEXT)\n  metadata    String?     @db.Text // JSON for rich content (images, links, etc.)\n\n  isRead Boolean   @default(false)\n  readAt DateTime?\n\n  createdAt DateTime @default(now())\n\n  @@index([roomId, createdAt])\n  @@index([senderId])\n}\n\n// ═══════════════════════════════════════════════════════════════\n// IM MODULE — Next-Gen Chat Infrastructure\n// Based on im_protocol_v2.proto & Power Board Rule Engine Spec\n// ═══════════════════════════════════════════════════════════════\n\n// Conversation — logical session layer (maps 1:1 with ChatRoom for migration)\nmodel Conversation {\n  id String @id @default(cuid())\n\n  // Participants\n  userAId     String\n  userA       User   @relation(\"ConversationUserA\", fields: [userAId], references: [id])\n  userBId     String\n  userB       User   @relation(\"ConversationUserB\", fields: [userBId], references: [id])\n  initiatorId String // who started the conversation\n\n  // Backlink to ChatRoom (migration bridge)\n  chatRoomId String?   @unique\n  chatRoom   ChatRoom? @relation(fields: [chatRoomId], references: [id])\n\n  // State\n  state       ConversationState @default(ACTIVE)\n  stateReason String? // reason for state change\n\n  // Female Control\n  controllingUserId     String? // who has control (usually female)\n  activeBoundaryVersion String? // current Power Board version\n\n  // Statistics (denormalized for performance)\n  lastMessageAt DateTime?\n  messageCount  Int       @default(0)\n  unreadCountA  Int       @default(0)\n  unreadCountB  Int       @default(0)\n\n  // Per-user settings (JSON for flexibility)\n  settings String? @db.Text // JSON: { userA: {muted, pinned}, userB: {muted, pinned} }\n\n  // Vault\n  vaultExpiresAt DateTime? // Vault expiry timestamp (null = no Vault)\n\n  // Consent cache\n  cachedConsentState ConsentState @default(CONSENT_NONE)\n\n  // Relations\n  participants    ConversationParticipant[]\n  imMessages      IMMessage[]\n  receipts        MessageReceipt[]\n  consentRequests ConsentRequest[]\n  consentGrants   ConsentGrant[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([userAId, userBId], map: \"unique_conversation_pair\")\n  @@index([state])\n  @@index([lastMessageAt])\n  @@index([userAId])\n  @@index([userBId])\n  @@index([controllingUserId])\n  @@index([vaultExpiresAt])\n}\n\n// ConversationParticipant — per-user conversation membership & state\nmodel ConversationParticipant {\n  id             String       @id @default(cuid())\n  conversationId String\n  conversation   Conversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n  userId         String\n  user           User         @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // Per-user state\n  isMuted     Boolean   @default(false)\n  isPinned    Boolean   @default(false)\n  isArchived  Boolean   @default(false)\n  lastReadSeq Int       @default(0) // last read sequence number\n  lastReadAt  DateTime?\n\n  // Subscription\n  subscribedAt DateTime @default(now())\n\n  @@unique([conversationId, userId])\n  @@index([userId])\n  @@index([userId, isMuted])\n  @@index([userId, isPinned])\n}\n\n// IMMessage — next-gen message model with seq, encryption, consent\nmodel IMMessage {\n  id             String       @id @default(cuid())\n  conversationId String\n  conversation   Conversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n\n  // Core fields\n  clientMsgId String? @unique // client-generated ID for dedup\n  senderId    String\n  sender      User    @relation(\"IMMessageSender\", fields: [senderId], references: [id])\n  receiverId  String\n  seq         Int // server-assigned sequence number (monotonic per conversation)\n\n  // Content\n  msgType  IMMessageType @default(TEXT)\n  payload  String        @db.Text // message content (plaintext or E2EE ciphertext)\n  metadata String?       @db.Text // JSON: media info, links, etc.\n\n  // Encryption\n  encryptionMode     EncryptionMode @default(SERVER)\n  ephemeralPublicKey String?        @db.Text // for E2EE key exchange\n\n  // Boundary & compliance (plaintext, for rule engine)\n  boundaryVersion String? // current Power Board version\n  complianceTags  String[]         @default([]) // [\"consent_granted\", \"media_level_2\", \"pace_ok\"]\n  consentState    ConsentState     @default(CONSENT_NONE)\n  mediaLevel      MediaAccessLevel @default(L0_TEXT)\n  ruleResult      RuleEngineResult @default(PASS)\n\n  // Reply\n  replyToMsgId   String?\n  replyToPreview String? @db.Text // JSON: {msgId, senderId, previewText, mediaLevel}\n\n  // Edit & Delete\n  isEdited  Boolean   @default(false)\n  editedAt  DateTime?\n  isDeleted Boolean   @default(false)\n  deletedAt DateTime?\n  deletedBy String? // who deleted (sender or admin)\n\n  // Media metadata\n  mediaMetadata String? @db.Text // JSON: {mediaId, level, mimeType, sizeBytes, width, height, durationMs, thumbnailUrl, watermarkHash, isExpiring, expiresAt}\n\n  // Delivery status\n  status MessageDeliveryStatus @default(SENT)\n\n  // Receipts\n  receipts MessageReceipt[]\n\n  // Reactions\n  reactions MessageReaction[]\n\n  createdAt DateTime @default(now())\n\n  @@index([conversationId, seq])\n  @@index([conversationId, createdAt])\n  @@index([senderId])\n  @@index([receiverId])\n  @@index([clientMsgId])\n  @@index([createdAt])\n  @@index([msgType])\n  @@index([isDeleted])\n}\n\n// MessageReceipt — per-recipient delivery & read receipts\nmodel MessageReceipt {\n  id             String       @id @default(cuid())\n  messageId      String\n  message        IMMessage    @relation(fields: [messageId], references: [id], onDelete: Cascade)\n  conversationId String\n  conversation   Conversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n  userId         String // who this receipt belongs to\n  user           User         @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // Receipt state\n  deliveredAt DateTime? // when message was delivered to this user\n  readAt      DateTime? // when message was read by this user\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([messageId, userId])\n  @@index([userId, readAt])\n  @@index([conversationId])\n}\n\n// MessageReaction — emoji reactions on messages\nmodel MessageReaction {\n  id        String    @id @default(cuid())\n  messageId String\n  message   IMMessage @relation(fields: [messageId], references: [id], onDelete: Cascade)\n  userId    String\n  user      User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // Emoji character (👍 ❤️ 😂 😮 😢 🔥 etc.)\n  emoji String\n\n  createdAt DateTime @default(now())\n\n  // Each user can only add one reaction per emoji per message\n  @@unique([messageId, userId, emoji])\n  @@index([messageId])\n  @@index([userId])\n}\n\n// UserPresence — online/offline status tracking\nmodel UserPresence {\n  id     String @id @default(cuid())\n  userId String @unique\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // Presence state\n  status        PresenceStatus @default(OFFLINE)\n  statusMessage String? // custom status text\n  lastSeenAt    DateTime? // last heartbeat / activity timestamp\n\n  // Device info\n  deviceId   String? // current active device\n  platform   String? // \"ios\", \"android\", \"web\"\n  appVersion String? // client version\n\n  // Connection\n  connectionId String? // WebSocket connection ID\n  connectedAt  DateTime? // when current session started\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([status])\n  @@index([lastSeenAt])\n  @@index([userId, status])\n}\n\n// ═══════════════════════════════════════════════════════════════\n// CONSENT MANAGEMENT — Granular permission control\n// ═══════════════════════════════════════════════════════════════\n\nmodel ConsentRequest {\n  id             String       @id @default(cuid())\n  requesterId    String\n  requester      User         @relation(\"ConsentRequester\", fields: [requesterId], references: [id])\n  targetId       String\n  target         User         @relation(\"ConsentTarget\", fields: [targetId], references: [id])\n  conversationId String\n  conversation   Conversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n\n  // Request details\n  consentType    ConsentRequestType @default(MEDIA)\n  requestedLevel MediaAccessLevel   @default(L0_TEXT)\n  contextMsgId   String? // message that triggered this request\n  reason         String?            @db.Text // user-visible reason\n\n  // Preview (encrypted)\n  previewPayload String? @db.Text // encrypted preview content\n\n  // State\n  state        ConsentState @default(CONSENT_PENDING)\n  respondedAt  DateTime?\n  responseNote String?\n  grantToken   String?      @unique // authorization token for verification\n\n  // Validity\n  expiresAt DateTime\n\n  createdAt DateTime @default(now())\n\n  @@index([requesterId])\n  @@index([targetId])\n  @@index([conversationId])\n  @@index([state])\n  @@index([expiresAt])\n  @@index([consentType])\n}\n\nmodel ConsentGrant {\n  id             String       @id @default(cuid())\n  granterId      String\n  granter        User         @relation(\"ConsentGranter\", fields: [granterId], references: [id])\n  granteeId      String\n  grantee        User         @relation(\"ConsentGrantee\", fields: [granteeId], references: [id])\n  conversationId String\n  conversation   Conversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n\n  // Grant details\n  consentType  ConsentRequestType @default(MEDIA)\n  grantedLevel MediaAccessLevel   @default(L0_TEXT)\n\n  // Validity\n  grantedAt DateTime  @default(now())\n  expiresAt DateTime? // null = permanent\n\n  // Revocation\n  isRevoked Boolean   @default(false)\n  revokedAt DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([granterId])\n  @@index([granteeId])\n  @@index([conversationId])\n  @@index([consentType])\n  @@index([isRevoked])\n  @@index([expiresAt])\n}\n\n// ═══════════════════════════════════════════════════════════════\n// POWER BOARD — Rule engine for boundary control\n// ═══════════════════════════════════════════════════════════════\n\nmodel PowerBoardRule {\n  id     String @id @default(cuid())\n  userId String @unique // each user has one active rule set\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // Version control\n  version  String  @default(\"1.0.0\") // semantic versioning\n  isActive Boolean @default(true)\n\n  // Pace Control (JSON)\n  paceConfig String @db.Text // JSON: {maxMessagesPerHour, maxMessagesPerDay, responseWindowHours, enforceCooldown, cooldownMinutes, showRemainingQuota}\n\n  // Media Policy (JSON)\n  mediaConfig String @db.Text // JSON: {defaultLevel, perUserOverride, requireConsentForUpgrade, autoBlurImages, watermarkAllMedia}\n\n  // Content Filter (JSON)\n  filterConfig String @db.Text // JSON: {blockedKeywords, blockedPatterns, blockExplicitImages, autoFlagProfanity, blockUnsolicitedContact, sensitivityLevel}\n\n  // Auto Response (JSON)\n  autoResponse String? @db.Text // JSON: {enabled, messageTemplate, triggerAfterHours, onlyFirstMessage}\n\n  // Privacy Settings (JSON)\n  privacyConfig String @db.Text // JSON: {preferredEncryption, allowScreenshotNotifications, autoExpireMessages, expireAfterDays, hideOnlineStatus, hideReadReceipts}\n\n  // Notification Preferences (JSON)\n  notifConfig String? @db.Text // JSON: {pushEnabled, soundEnabled, previewEnabled, quietHoursEnabled, quietHoursStart, quietHoursEnd}\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([userId])\n  @@index([version])\n  @@index([isActive])\n}\n\n// ═══════════════════════════════════════════════════════════════\n// AUDIT LOG — Immutable audit trail with hash chain\n// ═══════════════════════════════════════════════════════════════\n\nmodel AuditLog {\n  id             String  @id @default(cuid())\n  userId         String // who this log belongs to\n  user           User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  conversationId String? // related conversation\n\n  // Action details\n  action   String // \"boundary_changed\", \"consent_granted\", \"message_blocked\", \"rule_violation\", \"security_event\"\n  actorId  String? // who performed the action\n  targetId String? // who was affected\n\n  // Details (JSON - varies by action type)\n  details String? @db.Text // JSON with full context\n\n  // Hash chain (tamper detection)\n  prevHash  String? // hash of previous entry\n  entryHash String // hash of this entry\n\n  // Metadata\n  ipAddress String?\n  userAgent String? @db.Text\n  deviceId  String?\n\n  createdAt DateTime @default(now())\n\n  @@index([userId, createdAt])\n  @@index([conversationId])\n  @@index([action])\n  @@index([actorId])\n  @@index([createdAt])\n}\n\n// ═══════════════════════════════════════════════════════════════\n// NOTIFICATIONS\n// ═══════════════════════════════════════════════════════════════\n\nmodel Notification {\n  id     String @id @default(cuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  type      NotificationType\n  title     String\n  body      String           @db.Text\n  data      String?          @db.Text // JSON payload for deep links\n  actionUrl String?\n\n  isRead Boolean   @default(false)\n  readAt DateTime?\n\n  createdAt DateTime @default(now())\n\n  @@index([userId, isRead, createdAt])\n}\n\n// ═══════════════════════════════════════════════════════════════\n// PAYMENTS & SUBSCRIPTIONS\n// ═══════════════════════════════════════════════════════════════\n\nmodel Subscription {\n  id     String @id @default(cuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  plan   SubscriptionPlan\n  status SubscriptionStatus @default(ACTIVE)\n\n  // Stripe\n  stripeCustomerId       String?   @unique\n  stripePriceId          String?\n  stripeSubscriptionId   String?   @unique\n  stripeCurrentPeriodEnd DateTime?\n\n  // Matching perks\n  weeklyMatchLimit   Int     @default(5)\n  canInitiateChat    Boolean @default(true)\n  canViewFullProfile Boolean @default(true)\n\n  startsAt    DateTime  @default(now())\n  endsAt      DateTime?\n  cancelledAt DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([userId])\n  @@index([status])\n}\n\nmodel Payment {\n  id     String @id @default(cuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  stripePaymentIntentId String?       @unique\n  amount                Float // In USD\n  currency              String        @default(\"usd\")\n  status                PaymentStatus @default(PENDING)\n\n  description String?\n  metadata    String? @db.Text // JSON\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([userId])\n}\n\n// ═══════════════════════════════════════════════════════════════\n// ADMIN & ANALYTICS\n// ═══════════════════════════════════════════════════════════════\n\nmodel AdminLog {\n  id       String  @id @default(cuid())\n  authorId String?\n  author   User?   @relation(\"AdminLogAuthor\", fields: [authorId], references: [id])\n\n  action     String // \"user.approve\", \"match.review\", \"system.config\", etc.\n  targetId   String? // ID of the target resource\n  targetType String? // \"User\", \"Match\", \"Profile\", etc.\n  details    String? @db.Text // JSON with full context\n\n  ipAddress String?\n  userAgent String? @db.Text\n\n  createdAt DateTime @default(now())\n\n  @@index([authorId])\n  @@index([action])\n  @@index([createdAt])\n}\n\nmodel AnalyticsEvent {\n  id     String  @id @default(cuid())\n  userId String?\n  user   User?   @relation(fields: [userId], references: [id], onDelete: SetNull)\n\n  event      String // \"page.view\", \"match.viewed\", \"message.sent\", \"profile.completed\", etc.\n  properties String? @db.Text // JSON with event data\n\n  sessionId String?\n  ipAddress String?\n  userAgent String? @db.Text\n\n  createdAt DateTime @default(now())\n\n  @@index([userId, event, createdAt])\n  @@index([event, createdAt])\n}\n\nmodel SystemConfig {\n  key         String   @id\n  value       String   @db.Text\n  description String?\n  updatedAt   DateTime @updatedAt\n  updatedBy   String?\n}\n\n// ═══════════════════════════════════════════════════════════════\n// ENUMS\n// ═══════════════════════════════════════════════════════════════\n\nenum UserRole {\n  USER\n  ADMIN\n  SUPER_ADMIN\n}\n\nenum Gender {\n  MALE\n  FEMALE\n  NON_BINARY\n  OTHER\n}\n\nenum RelationshipGoal {\n  LONG_TERM // Seeking serious relationship\n  DATING // Open to exploring\n  FRIENDSHIP // Want connections first\n  NOT_SURE // Still figuring out\n}\n\nenum ProfileStatus {\n  DRAFT // Onboarding in progress\n  PENDING_REVIEW // Submitted, waiting for admin review\n  APPROVED // Ready for matching\n  REJECTED // Needs revision\n  DEACTIVATED // User deactivated\n  BANNED // Admin banned\n}\n\nenum MatchStatus {\n  PENDING // Created, waiting for reactions\n  ACCEPTED // Both accepted\n  REJECTED // One or both rejected\n  EXPIRED // Not acted upon within timeframe\n  CANCELLED // Admin cancelled\n}\n\nenum MatchType {\n  WEEKLY // Regular weekly match\n  BOOSTED // Premium priority match\n  MANUAL // Admin-curated match\n  AI_SUGGESTED // AI recommendation (requires approval)\n}\n\nenum MatchAction {\n  INTERESTED // \"I'd like to connect\"\n  PASS // \"Not for me right now\"\n  MAYBE // \"Tell me more\"\n  BLOCK // \"Don't match me with this person\"\n}\n\nenum MessageType {\n  TEXT\n  IMAGE\n  SYSTEM // Auto-generated messages\n  VOICE // Future: voice notes\n}\n\n// IM Module Message Types (extended from proto)\nenum IMMessageType {\n  TEXT\n  IMAGE\n  VOICE\n  FILE\n  SYSTEM\n  CONSENT_REQUEST\n  CONSENT_RESPONSE\n  RULE_UPDATE\n  TYPING\n  READ_RECEIPT\n}\n\nenum ConversationState {\n  ACTIVE\n  PAUSED // one party paused\n  BLOCKED\n  EXPIRED // auto-expired (e.g. Vault expired)\n  ARCHIVED\n}\n\nenum ConsentState {\n  CONSENT_NONE\n  CONSENT_PENDING\n  CONSENT_GRANTED\n  CONSENT_DENIED\n  CONSENT_EXPIRED\n}\n\nenum MediaAccessLevel {\n  L0_TEXT // text only\n  L1_IMAGE // static images\n  L2_VOICE // voice messages\n  L3_VIDEO // video / live calls\n  L4_LOCATION // location sharing\n  L5_CONTACT // contact info\n}\n\nenum RuleEngineResult {\n  PASS\n  SOFT_BLOCK // suggest adjustment, can override\n  HARD_BLOCK // forced block\n  PACE_LIMIT // rate limit\n}\n\nenum EncryptionMode {\n  E2EE // end-to-end encrypted\n  SERVER // server-readable (safety mode)\n  HYBRID // hybrid mode\n}\n\nenum MessageDeliveryStatus {\n  SENDING\n  SENT\n  DELIVERED\n  READ\n  FAILED\n}\n\nenum PresenceStatus {\n  ONLINE\n  AWAY\n  BUSY\n  OFFLINE\n}\n\nenum ConsentRequestType {\n  MEDIA\n  LOCATION\n  CONTACT\n  INTIMATE // intimate content\n}\n\nenum NotificationType {\n  NEW_MATCH\n  MATCH_ACCEPTED\n  MATCH_REJECTED\n  NEW_MESSAGE\n  WEEKLY_DIGEST\n  PROFILE_APPROVED\n  PROFILE_REJECTED\n  SUBSCRIPTION_EXPIRED\n  SYSTEM_ANNOUNCEMENT\n}\n\nenum SubscriptionPlan {\n  FREE\n  LADY_FREE\n  PREMIUM_MONTHLY\n  PREMIUM_YEARLY\n  LIFETIME\n}\n\nenum SubscriptionStatus {\n  ACTIVE\n  CANCELLED\n  EXPIRED\n  PAST_DUE\n  TRIALING\n}\n\nenum PaymentStatus {\n  PENDING\n  SUCCEEDED\n  FAILED\n  REFUNDED\n}\n\n// ═══════════════════════════════════════════════════════════════\n// PRODUCT OPTIMIZATION: Sincerity System & Vault\n// ═══════════════════════════════════════════════════════════════\n\nenum VaultStatus {\n  ACTIVE // 正常进行中\n  EXTENDED // 已延长\n  REVOKED // 被女性终止\n  EXPIRED // 时间到自动关闭\n}\n\nenum SincerityTransactionType {\n  EARN // 赚取\n  SPEND // 消费\n  RECEIVE_GIFT // 收到礼物\n  SEND_GIFT // 送出礼物\n  REFUND // 退款\n}\n\nmodel SincerityWallet {\n  id     String  @id @default(cuid())\n  userId String  @unique\n  user   Profile @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // Balance\n  balance       Int @default(0) // 当前余额\n  totalEarned   Int @default(0) // 累计获得\n  totalSpent    Int @default(0) // 累计消费\n  totalGifted   Int @default(0) // 累计送出礼物\n  totalReceived Int @default(0) // 累计收到礼物\n\n  // Tier System\n  tier         SincerityTier @default(BRONZE)\n  tierProgress Float         @default(0) // 到下一级的进度 0-100\n\n  // Stats\n  lastEarnedAt DateTime?\n  lastSpentAt  DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  transactions SincerityTransaction[]\n\n  @@index([tier])\n  @@index([balance])\n}\n\nmodel SincerityTransaction {\n  id       String          @id @default(cuid())\n  walletId String\n  wallet   SincerityWallet @relation(fields: [walletId], references: [id], onDelete: Cascade)\n\n  // Transaction Details\n  type   SincerityTransactionType\n  amount Int\n\n  // Source/Reason\n  source      String // \"PROFILE_COMPLETE\", \"DAILY_LOGIN\", \"MATCH_ACCEPTED\", \"PITCH_SEND\", etc.\n  description String? // 用户可见的描述\n\n  // Related Entities\n  matchId    String? // 关联的匹配\n  fromUserId String? // 送礼人\n  toUserId   String? // 收礼人\n  message    String? // 附言\n\n  // Metadata\n  metadata String? @db.Text // JSON for additional data\n\n  createdAt DateTime @default(now())\n\n  @@index([walletId])\n  @@index([type])\n  @@index([createdAt])\n  @@index([source])\n}\n\nenum SincerityTier {\n  BRONZE // 0-499\n  SILVER // 500-1999\n  GOLD // 2000-4999\n  PLATINUM // 5000+\n}\n\n// ═══════════════════════════════════════════════════════════════\n// SAFETY & MODERATION — User Reports\n// ═══════════════════════════════════════════════════════════════\n\nenum ReportReason {\n  INAPPROPRIATE_CONTENT\n  HARASSMENT\n  FAKE_PROFILE\n  SPAM\n  OFFENSIVE_BEHAVIOR\n  OTHER\n}\n\nenum ReportStatus {\n  PENDING\n  UNDER_REVIEW\n  RESOLVED_NO_ACTION\n  RESOLVED_WARNING\n  RESOLVED_BANNED\n  DISMISSED\n}\n\nmodel UserReport {\n  id String @id @default(cuid())\n\n  // Reporter (who made the report)\n  reporterId String\n  reporter   User   @relation(\"ReportsMade\", fields: [reporterId], references: [id], onDelete: Cascade)\n\n  // Reported user (who was reported)\n  reportedUserId String\n  reportedUser   User   @relation(\"ReportsReceived\", fields: [reportedUserId], references: [id], onDelete: Cascade)\n\n  // Report details\n  reason      ReportReason\n  description String?      @db.Text\n\n  // Context (optional)\n  chatRoomId String?\n  messageId  String?\n\n  // Status tracking\n  status     ReportStatus @default(PENDING)\n  reviewedBy String? // Admin user ID\n  reviewedAt DateTime?\n  adminNotes String?      @db.Text\n\n  // Resolution\n  actionTaken String? // \"WARNING\", \"BAN\", \"NONE\", etc.\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([reporterId])\n  @@index([reportedUserId])\n  @@index([status])\n  @@index([createdAt])\n  @@index([reporterId, reportedUserId, createdAt])\n}\n"
}

